export type MultiColorFillMode = 'normal' | 'hard';

export interface MultiColorFillLevel {
    readonly id: string;
    readonly width: number;
    readonly height: number;
    readonly blocked: readonly number[];
    readonly starts: readonly number[];
    /** 每色覆盖格数包含起点；等于原题 movesPerColor + 1。 */
    readonly lengths: readonly number[];
    readonly solution: readonly (readonly number[])[];
    readonly difficulty: number;
    readonly stage: string;
}

export interface MultiColorFillCatalog {
    readonly length: number;
    get(index: number): MultiColorFillLevel;
}

