const CELL_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";
export const MULTI_COLOR_FILL_STAGES: Readonly<Record<MultiColorFillMode, readonly string[]>> = {"normal":["彩路起步","转弯练习","交错路线","通道分配","多色协作","空间取舍","路线规划","复杂布局","全盘推演","普通终章"],"hard":["超难启程","岔路抉择","瓶颈穿行","长线布局","密集推演","多路交织","空间博弈","深度规划","极限布局","超难终章"]};

class FixedFillCatalog implements MultiColorFillCatalog {
    readonly length: number;
    private cachedIndex = -1;
    private cachedLevel?: MultiColorFillLevel;
    constructor(private readonly records: readonly string[], private readonly stages: readonly string[]) {
        this.length = records.length;
    }
    get(index: number): MultiColorFillLevel {
        if (!Number.isInteger(index) || index < 0 || index >= this.length) throw new RangeError('Invalid fill level index');
        if (this.cachedIndex === index && this.cachedLevel) return this.cachedLevel;
        const fields = this.records[index].split('|'), position = parseInt(fields[1], 36);
        const sectionSize = fields[0] === '8' ? 2301 : 1710;
        const decode = (cells: string): number[] => cells.split('').map(cell => CELL_ALPHABET.indexOf(cell));
        const solution = fields[7].split('/').map(decode);
        const level: MultiColorFillLevel = {
            id: `levels_all_ad${fields[0]}_${Math.floor(position / sectionSize)}#${position % sectionSize}`,
            width: Number(fields[2]), height: Number(fields[3]), blocked: decode(fields[6]),
            starts: solution.map(route => route[0]), lengths: solution.map(route => route.length), solution,
            difficulty: parseInt(fields[4], 36) / 1000, stage: this.stages[Number(fields[5])],
        };
        this.cachedIndex = index; this.cachedLevel = level; return level;
    }
}

